export class Store {
  constructor() { this.entries = new Map(); }
  save(key, value) { this.entries.set(key, value); }
  get(key) { return this.entries.get(key); }
}

import { Store } from './store.js';
export class Loader {
  constructor(store = new Store(), clock = Date) {
    this.store = store; this.clock = clock;
  }
  async load(read, notify) {
    const text = await read();
    const value = JSON.parse(text);
    this.store.save('current', value);
    notify(value, this.clock.now());
    return value;
  }
}

import { Store } from './store.js';
export async function show(loader, read, view) {
  if (typeof read !== 'function') throw new Error('Reader required');
  const value = await loader.load(read, () => {});
  view.render(value);
}
export const sharedStore = new Store();

import { Store } from '../src/store.js';
const store = new Store();
store.save('example', 42);
if (store.get('example') !== 42) throw new Error('Round trip failed');
